}

describe('Classic command check evidence', () => {
  let projectRoot: string;
  let changeDir: string;
  let run: RunState;

  beforeEach(async () => {
    projectRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-command-check-'));
    await prepareClassicLegacyProject(projectRoot);
    changeDir = path.join(projectRoot, 'openspec', 'changes', 'demo');
    await fs.mkdir(changeDir, { recursive: true });
    run = runState();
    await writeClassicState(changeDir, { classic: classicFixture(), run });
  });

  function classicFixture() {
    return parseClassicStateDocument({
      workflow: 'full',
      phase: 'build',
      design_doc: null,
      plan: null,
      build_mode: 'direct',
      isolation: 'current',
      verify_mode: 'light',
      verify_result: 'pending',
      verified_at: null,
      archived: false,
    }).classic!;
  }

  afterEach(async () => {
    vi.restoreAllMocks();
    await fs.rm(projectRoot, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
  });

  it.each([0, 7])(
    'returns the original actual result for a repeated check request (exit=%s)',
    async (exitCode) => {
      const counter = `${projectRoot}-execution-count`;
      try {
        const input = {
          scope: 'verify' as const,
          argv: [
            process.execPath,
            '-e',
            `require('node:fs').appendFileSync(${JSON.stringify(counter)}, 'x'); process.exit(${exitCode})`,
          ],
          reusable: true,
          executionRequestId: 'a'.repeat(64),
        };
        const original = await executeCommandCheck(projectRoot, changeDir, run, input);
        const repeated = await executeCommandCheck(projectRoot, changeDir, run, input);
        expect(original.exitCode).toBe(exitCode);
        expect(repeated).toEqual({ ...original, reused: true });
        expect(await fs.readFile(counter, 'utf8')).toBe('x');
        expect(
          (await readTrajectory(changeDir, run.trajectoryRef)).filter(
            (event) => event.type === 'command_check_started',
          ),
        ).toHaveLength(1);
      } finally {
        await fs.rm(counter, { force: true });
      }
    },
  );

  it('retries only a proven prelaunch failure in the same check Action without replaying a process', async () => {
    const counter = `${projectRoot}-execution-count`;
    try {
      const input = {
        scope: 'verify' as const,
        argv: [
          process.execPath,
          '-e',
          `require('node:fs').appendFileSync(${JSON.stringify(counter)},'x')`,
        ],
        reusable: true,
        executionRequestId: 'b'.repeat(64),
      };
      // 旧版确实在启动前中断的持久化记录；没有启动任何检查进程。
      const action = startClassicCheckAction({
        run,
        id: input.executionRequestId,
        scope: input.scope,
        argv: input.argv,
        cwd: '.',
        timeoutMs: 300000,
        tier: 'full',
        checkEpoch: 0,
      });
      await appendTrajectory(changeDir, run.trajectoryRef, {
        sequence: 1,
        timestamp: new Date().toISOString(),
        runId: run.runId,
        type: 'command_check_started',
        data: {
          scope: input.scope,
          argv: input.argv,
          cwd: '.',
          timeoutMs: 300000,
          reusable: true,
          tier: 'full',
          checkEpoch: 0,
          action,
        },
      });
      await appendTrajectory(changeDir, run.trajectoryRef, {
        sequence: 2,
        timestamp: new Date().toISOString(),
        runId: run.runId,
        type: 'checkpoint',
        data: {
          kind: 'classic-check-not-executed',
          scope: input.scope,
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          reason: 'Original input read stopped before launch.',
        },
      });
      expect(await latestCommandCheck(projectRoot, changeDir, run, 'verify')).toBeNull();
      expect(await fs.stat(counter).catch(() => null)).toBeNull();
      const resumed = await executeCommandCheck(projectRoot, changeDir, run, input);
      expect(resumed.action).toMatchObject({
        id: input.executionRequestId,
        attempt: 2,
        status: 'succeeded',
      });
      expect(resumed.action?.reconciliations).toEqual([
        expect.objectContaining({ attempt: 1, resolution: 'not-executed' }),
      ]);
      expect(await fs.readFile(counter, 'utf8')).toBe('x');
      expect(await executeCommandCheck(projectRoot, changeDir, run, input)).toEqual({
        ...resumed,
        reused: true,
      });
      expect(await fs.readFile(counter, 'utf8')).toBe('x');
    } finally {
      await fs.rm(counter, { force: true });
    }
  });

  it('refuses both old and new request IDs when the process ran but its completion receipt is unknown', async () => {
    const counter = `${projectRoot}-execution-count`;
    try {
      const input = {
        scope: 'verify' as const,
        argv: [
          process.execPath,
          '-e',
          `require('node:fs').appendFileSync(${JSON.stringify(counter)},'x')`,
        ],
        reusable: true,
        executionRequestId: 'c'.repeat(64),
      };
      vi.spyOn(checkFiles, 'writeClassicProjectText').mockRejectedValueOnce(
        new Error('completion receipt unavailable'),
      );
      await expect(executeCommandCheck(projectRoot, changeDir, run, input)).rejects.toThrow(
        'receipt unavailable',
      );
      expect(await fs.readFile(counter, 'utf8')).toBe('x');
      expect(await latestCommandCheck(projectRoot, changeDir, run, 'verify')).toBeNull();
      await expect(executeCommandCheck(projectRoot, changeDir, run, input)).rejects.toThrow(
        '结果未明',
      );
      await expect(
        executeCommandCheck(projectRoot, changeDir, run, {
          ...input,
          executionRequestId: 'd'.repeat(64),
        }),
      ).rejects.toThrow('结果未明');
      expect(await fs.readFile(counter, 'utf8')).toBe('x');
    } finally {
      await fs.rm(counter, { force: true });
    }
  });

  it('appends command evidence without executing the saved command', async () => {
    const marker = path.join(projectRoot, 'must-not-exist');
    const recorded = await recordCommandCheck(projectRoot, changeDir, run, {
      scope: 'build',
      command: `node -e "require('fs').writeFileSync('${marker}', 'bad')"`,
      exitCode: 0,
      cwd: 'packages/app',
    });

    expect(recorded).toMatchObject({
      scope: 'build',
      exitCode: 0,
      cwd: 'packages/app',
      runId: 'run-current',
    });
    expect(await fs.stat(marker).catch(() => null)).toBeNull();
    expect(await readTrajectory(changeDir, run.trajectoryRef)).toEqual([
      expect.objectContaining({
        sequence: 1,
        type: 'command_check_recorded',
        runId: 'run-current',
        data: expect.objectContaining({ scope: 'build', exitCode: 0, cwd: 'packages/app' }),
      }),
    ]);
  });

  it('serializes concurrent evidence sequence allocation', async () => {
    const results = await Promise.all(
      Array.from({ length: 4 }, (_, index) =>
        recordCommandCheck(projectRoot, changeDir, run, {
          scope: 'verify',
          command: `check-${index}`,
          exitCode: index,
        }),
      ),
    );
    expect(results.map((record) => record.sequence).sort()).toEqual([1, 2, 3, 4]);
    expect(await latestCommandCheck(projectRoot, changeDir, run, 'verify')).toEqual(
      results.find((record) => record.sequence === 4),
    );
  });

  it.each([
    'command_check_started',
    'command_check_consumed',
    'command_checks_invalidated',
  ] as const)('preserves %s fences after warming the index', async (type) => {
    await recordCommandCheck(projectRoot, changeDir, run, {
      scope: 'build',
      command: 'check',
      exitCode: 0,
    });
    expect(await latestCommandCheck(projectRoot, changeDir, run, 'build')).not.toBeNull();
    await appendTrajectory(changeDir, run.trajectoryRef, {
      sequence: 2,
      timestamp: '',
      runId: run.runId,
      type,
      data: { scope: 'build', scopes: ['build'] },
    });
    expect(await latestCommandCheck(projectRoot, changeDir, run, 'build')).toBeNull();
  });

  it('does not resurrect an older execution over a newer start', async () => {
    const execution = executeCommandCheck(projectRoot, changeDir, run, {
      scope: 'verify',
      argv: [process.execPath, '-e', 'setTimeout(() => {}, 1000)'],
      reusable: true,
    });
    const outcome = execution.then(
      () => 'unexpected success',
      (error: Error) => error.message,
    );
    for (let attempt = 0; attempt < 100; attempt++) {
      if (
        (await readTrajectory(changeDir, run.trajectoryRef)).some(
          (event) => event.type === 'command_check_started',
        )
      )
        break;
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
    await appendTrajectory(changeDir, run.trajectoryRef, {
      sequence: 2,
      timestamp: '',
      runId: run.runId,
      type: 'command_check_started',
      data: { scope: 'verify' },
    });
    expect(await outcome).toMatch(/superseded/i);
    expect(await usableCommandCheck(projectRoot, changeDir, run, 'verify')).toBeNull();
  });

  it('returns the newest valid matching record, including failures, for only the current run', async () => {
    const oldRun = runState('run-old');
    await recordCommandCheck(projectRoot, changeDir, run, {
      scope: 'verify',
      command: 'npm test',
      exitCode: 0,
    });
    await recordCommandCheck(projectRoot, changeDir, oldRun, {
      scope: 'verify',
      command: 'old run failure',
      exitCode: 9,
    });
    await appendTrajectory(changeDir, run.trajectoryRef, {
      sequence: 3,
      timestamp: new Date().toISOString(),
      type: 'command_check_recorded',
      runId: run.runId,
      data: { scope: 'verify', command: '', exitCode: 7, cwd: '.' },
    } as TrajectoryEvent);
    const failure = await recordCommandCheck(projectRoot, changeDir, run, {
      scope: 'verify',
      command: 'npm test -- --runInBand',
      exitCode: 2,
    });

    expect(await latestCommandCheck(projectRoot, changeDir, run, 'verify')).toEqual(failure);
    expect(await latestCommandCheck(projectRoot, changeDir, run, 'build')).toBeNull();
  });

  it('ignores newer records with invalid cwd and normalizes the older valid cwd', async () => {
    const timestamp = new Date().toISOString();
    const events = [
      { sequence: 1, cwd: 'packages/../src', command: 'npm run build' },
      { sequence: 2, cwd: '', command: 'blank cwd' },
      { sequence: 3, cwd: '../outside', command: 'traversal cwd' },
      { sequence: 4, cwd: path.resolve(projectRoot, '..', 'outside'), command: 'absolute cwd' },
    ];
    for (const event of events) {
      await appendTrajectory(changeDir, run.trajectoryRef, {
        sequence: event.sequence,
        timestamp,
        type: 'command_check_recorded',
        runId: run.runId,
        data: { scope: 'build', command: event.command, exitCode: 0, cwd: event.cwd },
      });
    }

    expect(await latestCommandCheck(projectRoot, changeDir, run, 'build')).toEqual({
      sequence: 1,
      timestamp,
      runId: run.runId,
      scope: 'build',
      command: 'npm run build',
      exitCode: 0,
      cwd: 'src',
    });
  });

  it('rejects a check when a persisted Run belongs to a different execution', async () => {
    await writeClassicState(changeDir, {
      ...(await readClassicState(changeDir)),
      run: runState('another-run'),
    });
    await expect(
      executeCommandCheck(projectRoot, changeDir, run, {
        scope: 'build',
        argv: [process.execPath, '-e', 'process.exit(0)'],
      }),
    ).rejects.toThrow('Classic check Run changed before launch');
  });

  it.each([
    ['null data', null],
    ['missing data', undefined],
    ['array data', []],
  ])('ignores a newer record with %s', async (_label, malformedData) => {
    const valid = await recordCommandCheck(projectRoot, changeDir, run, {
      scope: 'verify',
      command: 'npm test',
      exitCode: 0,
    });
    const malformed = {
      sequence: 2,
      timestamp: new Date().toISOString(),
      type: 'command_check_recorded',
      runId: run.runId,
      ...(malformedData === undefined ? {} : { data: malformedData }),
    } as unknown as TrajectoryEvent;
    await appendTrajectory(changeDir, run.trajectoryRef, malformed);

    await expect(latestCommandCheck(projectRoot, changeDir, run, 'verify')).resolves.toEqual(valid);
  });

  it.each([
    [{ scope: 'deploy', command: 'npm test', exitCode: 0 }, /scope/i],
    [{ scope: 'build', command: '   ', exitCode: 0 }, /command/i],
    [{ scope: 'build', command: 'npm test', exitCode: 0.5 }, /exitCode/i],
    [{ scope: 'build', command: 'npm test', exitCode: 0, cwd: '../outside' }, /project root/i],
  ])('rejects invalid evidence %#', async (input, message) => {
    await expect(recordCommandCheck(projectRoot, changeDir, run, input as never)).rejects.toThrow(
      message,
    );
  });

  it('reuses an explicitly selected original command without a file manifest', async () => {
    const recorded = await executeCommandCheck(projectRoot, changeDir, run, {
      scope: 'build',
      argv: [process.execPath, '-e', 'process.exit(0)'],
      reusable: true,
    });
    expect(recorded.exitCode).toBe(0);
    expect(recorded.reusable).toBe(true);
    expect(recorded.manifestRef).toBeUndefined();
    expect(recorded.manifestHash).toBeUndefined();
    expect(await usableCommandCheck(projectRoot, changeDir, run, 'build')).toMatchObject({
      sequence: recorded.sequence,
    });
    const again = await executeCommandCheck(projectRoot, changeDir, run, {
      scope: 'build',
      argv: [process.execPath, '-e', 'process.exit(0)'],
      reusable: true,
    });
    expect(again.reused).toBe(true);
  });

  it('reuses the same reusable command across Build and Verify without rerunning it', async () => {
    const marker = path.join(changeDir, '.comet', 'check-count.txt');
    await fs.mkdir(path.dirname(marker), { recursive: true });
    const argv = [
      process.execPath,
      '-e',
      `require('fs').appendFileSync(${JSON.stringify(marker)}, 'run\\n')`,
    ];
    const build = await executeCommandCheck(projectRoot, changeDir, run, {
      scope: 'build',
      argv,
      reusable: true,
    });
    const verify = await executeCommandCheck(projectRoot, changeDir, run, {
      scope: 'verify',
      argv,
      reusable: true,
    });

    expect(build.reused).toBeUndefined();
    expect(verify).toMatchObject({ scope: 'verify', reused: true, exitCode: 0 });
    expect(await fs.readFile(marker, 'utf8')).toBe('run\n');
    expect(await usableCommandCheck(projectRoot, changeDir, run, 'verify')).toMatchObject({
      sequence: verify.sequence,
    });
  });

  it('does not append duplicate cold-recovery fences after an unrelated checkpoint', async () => {
    await expect(recoverCommandChecks(projectRoot, changeDir, run)).resolves.toEqual({
      build: 'rerun-required',
      verify: 'rerun-required',
    });
    const first = await readTrajectory(changeDir, run.trajectoryRef);
    expect(first.filter((event) => event.type === 'command_checks_invalidated')).toHaveLength(1);

    await appendTrajectory(changeDir, run.trajectoryRef, {
      sequence: first.at(-1)!.sequence + 1,
      timestamp: new Date().toISOString(),
      runId: run.runId,
      type: 'checkpoint',
      data: { note: 'unrelated progress checkpoint' },
    });
    await expect(recoverCommandChecks(projectRoot, changeDir, run)).resolves.toEqual({
      build: 'rerun-required',
      verify: 'rerun-required',
    });

    const second = await readTrajectory(changeDir, run.trajectoryRef);
    expect(second.filter((event) => event.type === 'command_checks_invalidated')).toHaveLength(1);
  });
});

import { promises as fs } from 'fs';
import os from 'os';
import path from 'path';
import { spawnSync } from 'child_process';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { resolveCometResumeProbe } from '../../../domains/comet-classic/classic-resume-probe.js';

let tmpDir: string;

async function writeFile(filePath: string, content: string): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, content, 'utf8');
}

async function createChange(
  name: string,
  yaml: string,
  files: Record<string, string> = {},
): Promise<void> {
  const root = path.join(tmpDir, 'openspec', 'changes', name);
  await writeFile(path.join(root, '.comet.yaml'), yaml);
  await writeFile(path.join(root, 'proposal.md'), files['proposal.md'] ?? 'Improve cache ttl\n');
  await writeFile(path.join(root, 'design.md'), files['design.md'] ?? 'Cache ttl design\n');
  await writeFile(path.join(root, 'tasks.md'), files['tasks.md'] ?? '- [ ] Update cache ttl\n');
  await writeFile(
    path.join(tmpDir, 'docs', 'superpowers', 'specs', 'cache-ttl.md'),
    '# Cache TTL\n',
  );
  await writeFile(
    path.join(tmpDir, 'docs', 'superpowers', 'plans', 'cache-ttl.md'),
    '- [ ] Update cache ttl\n',
  );
}

function git(args: string[]): void {
  const result = spawnSync('git', args, {
    cwd: tmpDir,
    encoding: 'utf8',
  });
  if (result.status !== 0) {
    throw new Error(`git ${args.join(' ')} failed: ${result.stderr || result.stdout}`);
  }
}

const buildYaml = [
  'workflow: full',
  'phase: build',
  'archived: false',
  'build_pause: null',
  'isolation: branch',
  'build_mode: executing-plans',
  'tdd_mode: tdd',
  'review_mode: standard',
  'verify_mode: full',
  'verified_at: null',
  'verify_result: pending',
  'auto_transition: true',
  'design_doc: docs/superpowers/specs/cache-ttl.md',
  'plan: docs/superpowers/plans/cache-ttl.md',
  '',
].join('\n');

describe('resolveCometResumeProbe', () => {
  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-resume-probe-'));
    await writeFile(
      path.join(tmpDir, '.comet', 'config.yaml'),
      [
        'schema: comet.project.v1',
        'default_workflow: classic',
        'workflows: [classic]',
        'classic:',
        '  artifact_layout: legacy',
        '',
      ].join('\n'),
    );
    await fs.mkdir(path.join(tmpDir, 'openspec', 'changes'), { recursive: true });
  });

  afterEach(async () => {
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it('returns none when no active Comet changes exist', async () => {
    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: 'continue',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'none',
      confidence: 'none',
      changeName: null,
      nextCommand: null,
    });
  });

  it('finds an archived change whose authorized delivery is still pending', async () => {
    const archivedRoot = path.join(
      tmpDir,
      'openspec',
      'changes',
      'archive',
      '2026-09-21-cache-ttl',
    );
    await writeFile(
      path.join(archivedRoot, '.comet.yaml'),
      [
        'workflow: full',
        'phase: archive',
        'archived: true',
        'verify_result: pass',
        'created_at: 2026-09-21T00:00:00.000Z',
        'base_ref: main',
        'design_doc: null',
        'plan: null',
        'build_mode: null',
        'isolation: current',
        'verify_mode: full',
        'verified_at: 2026-09-21T00:00:00.000Z',
        '',
      ].join('\n'),
    );
    await writeFile(path.join(archivedRoot, 'proposal.md'), 'Improve cache ttl\n');
    await writeFile(path.join(archivedRoot, 'design.md'), 'Cache ttl design\n');
    await writeFile(path.join(archivedRoot, 'tasks.md'), '- [x] Update cache ttl\n');

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续完成刚才的交付',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'ask_user',
      changeName: 'cache-ttl',
      phase: 'archive',
      nextCommand: '/comet-archive',
    });
    expect(result.reason).toContain('pending delivery');
  });

  it('does not offer Archive continuation for a copied SDK archive without Run history', async () => {
    const archivedRoot = path.join(
      tmpDir,
      'openspec',
      'changes',
      'archive',
      '2026-09-21-copied-archive',
    );
    await writeFile(
      path.join(archivedRoot, '.comet.yaml'),
      [
        '# comet-execution: managed-run',
        'workflow: full',
        'phase: archive',
        'archived: true',
        'verify_result: pass',
        'design_doc: null',
        'plan: null',
        'build_mode: null',
        'isolation: current',
        'verify_mode: full',
        'verified_at: 2026-09-21T00:00:00.000Z',
        '',
      ].join('\n'),
    );

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续 copied-archive',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });
    expect(result).toMatchObject({
      action: 'ask_user',
      changeName: 'copied-archive',
      nextCommand: null,
    });
  });

  it('ignores non-change files in the Classic changes directory', async () => {
    await writeFile(path.join(tmpDir, 'openspec', 'changes', 'README.txt'), 'notes\n');

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: 'continue',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result.action).toBe('none');
  });

  it('auto resumes a single active change for resume-like work', async () => {
    await createChange('cache-ttl', buildYaml);

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续刚才的任务',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'auto_resume',
      confidence: 'high',
      changeName: 'cache-ttl',
      phase: 'build',
      nextCommand: '/comet-build',
    });
  });

  it('resumes the configured Classic root without scanning the standalone OpenSpec root', async () => {
    await createChange('legacy-change', buildYaml);
    await writeFile(
      path.join(tmpDir, 'docs', 'openspec', 'changes', 'docs-change', 'proposal.md'),
      '# Docs change\n',
    );

    await expect(
      resolveCometResumeProbe(tmpDir, {
        schema_version: 'comet.resume_probe.v1',
        utterance: '继续刚才的任务',
        agent_context: { non_trivial_work: true, already_in_comet_flow: false },
      }),
    ).resolves.toMatchObject({
      action: 'auto_resume',
      changeName: 'legacy-change',
      phase: 'build',
    });
  });

  it('fails closed when an active change directory is a junction', async () => {
    const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-resume-probe-outside-'));
    try {
      const outsideChange = path.join(outside, 'cache-ttl');
      await writeFile(path.join(outsideChange, '.comet.yaml'), buildYaml);
      await writeFile(path.join(outsideChange, 'proposal.md'), 'outside marker\n');
      await fs.symlink(
        outsideChange,
        path.join(tmpDir, 'openspec', 'changes', 'cache-ttl'),
        process.platform === 'win32' ? 'junction' : 'dir',
      );

      await expect(
        resolveCometResumeProbe(tmpDir, {
          schema_version: 'comet.resume_probe.v1',
          utterance: '继续 cache-ttl',
          agent_context: { non_trivial_work: true, already_in_comet_flow: false },
        }),
      ).rejects.toThrow(/symbolic link or junction/iu);
      expect(await fs.readFile(path.join(outsideChange, 'proposal.md'), 'utf8')).toBe(
        'outside marker\n',
      );
    } finally {
      await fs.rm(outside, { recursive: true, force: true });
    }
  });

  it('does not rewrite legacy command fields while probing', async () => {
    await createChange('cache-ttl', `${buildYaml}build_command: npm test\n`);
    const yamlPath = path.join(tmpDir, 'openspec', 'changes', 'cache-ttl', '.comet.yaml');
    const before = await fs.readFile(yamlPath, 'utf8');

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续刚才的任务',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result.action).toBe('auto_resume');
    expect(await fs.readFile(yamlPath, 'utf8')).toBe(before);
  });

  it('asks before resuming when the worktree has unattributed changes', async () => {
    await createChange('cache-ttl', buildYaml);
    git(['init']);
    await writeFile(path.join(tmpDir, 'README.md'), 'dirty user edit\n');

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续刚才的任务',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'ask_user',
      confidence: 'low',
      changeName: 'cache-ttl',
    });
    expect(result.reason).toContain('uncommitted');
  });

  it('does not auto resume from a single generic token match', async () => {
    await createChange('cache-ttl', buildYaml, {
      'tasks.md': '- [ ] Update cache ttl\n',
    });

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: 'update README badges',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result.action).toBe('ask_user');
    expect(result.reason).toContain('looks unrelated');
  });

  it('asks when an OpenSpec change exists without Comet state', async () => {
    const root = path.join(tmpDir, 'openspec', 'changes', 'cache-ttl');
    await writeFile(path.join(root, 'proposal.md'), 'Improve cache ttl\n');
    await writeFile(path.join(root, 'tasks.md'), '- [ ] Update cache ttl\n');

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续 cache-ttl',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'ask_user',
      confidence: 'low',
      changeName: 'cache-ttl',
      nextCommand: null,
    });
    expect(result.reason).toContain('missing Comet state');
  });

  it('auto resumes when the request names the active change', async () => {
    await createChange('cache-ttl', buildYaml);

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续 cache-ttl',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result.action).toBe('auto_resume');
    expect(result.evidence.some((item) => item.quote.includes('cache-ttl'))).toBe(true);
  });

  it('asks the user when a single active change exists but the request is a new topic', async () => {
    await createChange('cache-ttl', buildYaml);

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '给 README 加安装截图',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'ask_user',
      confidence: 'low',
      changeName: 'cache-ttl',
      nextCommand: '/comet-build',
    });
    expect(result.reason).toContain('looks unrelated');
  });

  it('asks the user and does not suggest nextCommand when state is missing required fields', async () => {
    const invalidBuildYaml = buildYaml
      .replace('verify_mode: full\n', '')
      .replace('verified_at: null\n', '');
    await createChange('cache-ttl', invalidBuildYaml);

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续刚才的任务',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'ask_user',
      confidence: 'low',
      changeName: 'cache-ttl',
      nextCommand: null,
    });
    expect(result.reason).toContain('decision point');
  });

  it('returns out_of_scope for pure questions', async () => {
    await createChange('cache-ttl', buildYaml);

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '这个探针靠谱吗',
      agent_context: { non_trivial_work: false, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'out_of_scope',
      confidence: 'low',
      nextCommand: null,
    });
  });

  it('asks the user for multiple active changes without a named change', async () => {
    await createChange('cache-ttl', buildYaml);
    await createChange('eval-noise', buildYaml.replace('Cache ttl design', 'Eval noise design'));

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result.action).toBe('ask_user');
    expect(result.reason).toContain('multiple active changes');
  });

  it('does not auto resume a named change while the worktree has unattributed changes', async () => {
    await createChange('cache-ttl', buildYaml);
    await createChange('eval-noise', buildYaml.replace('Cache ttl design', 'Eval noise design'));
    git(['init']);
    await writeFile(path.join(tmpDir, 'notes.md'), 'manual edit\n');

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: 'continue cache-ttl',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result).toMatchObject({
      action: 'ask_user',
      confidence: 'low',
      changeName: 'cache-ttl',
    });
    expect(result.reason).toContain('uncommitted');
  });

  it('asks the user when build is waiting at plan-ready', async () => {
    await createChange(
      'cache-ttl',
      buildYaml.replace('build_pause: null', 'build_pause: plan-ready'),
    );

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '继续',
      agent_context: { non_trivial_work: true, already_in_comet_flow: false },
    });

    expect(result.action).toBe('ask_user');
    expect(result.reason).toContain('decision point');
  });

  it('honors explicit opt-out wording', async () => {
    await createChange('cache-ttl', buildYaml);

    const result = await resolveCometResumeProbe(tmpDir, {
      schema_version: 'comet.resume_probe.v1',
      utterance: '不要恢复 workflow，直接解释这个文件',
      agent_context: { non_trivial_work: false, already_in_comet_flow: false },
    });

    expect(result.action).toBe('out_of_scope');
    expect(result.reason).toContain('opted out');
  });
});

