  run: WorkflowRun,
  projectRoot: string,
  phase: 'verify' | 'archive',
) {
  await registerSdkChangeOwner(projectRoot, {
    schema: 'comet.change-owner.v1',
    workflow: 'classic',
    change: 'example',
    format: 'sdk',
