        'native:',
        '  artifact_root: docs',
        '',
      ].join('\n'),
    );
    expect((withoutMemory.config as unknown as { memory: unknown }).memory).toEqual({
      learning: true,
      retrieval: true,
    });

    const disabled = parseWorkflowProjectConfigDocument(
      [
        'schema: comet.project.v1',
        'default_workflow: native',
        'workflows: [native]',
        'memory:',
        '  learning: false',
        '  retrieval: true',
        'native:',
        '  artifact_root: docs',
