      let { run } = await f.inspect();
      const action = run.actions.find((a) => a.stepId === 'tweak.archive.execute')!;
      expect(action.status).toBe(legacyUnknown ? 'unknown' : 'failed');
      if (!legacyUnknown)
        expect(action.outcome?.output).toMatchObject({
